// Registra o inicio do followup com os dados do checklist enviado
const dados = $input.first().json.body || $input.first().json;
const agora = new Date();

// Calcular datas dos lembretes
const data3dias = new Date(agora.getTime() + 3 * 86400000).toISOString();
const data7dias = new Date(agora.getTime() + 7 * 86400000).toISOString();
const data14dias = new Date(agora.getTime() + 14 * 86400000).toISOString();

console.log('Followup iniciado para checklist:', dados.checklist_id, '| Fornecedor:', dados.Fornecedor);

return [{
  json: {
    ...dados,
    status_followup: 'INICIADO',
    data_inicio_followup: agora.toISOString(),
    data_lembrete_1: data3dias,
    data_lembrete_2: data7dias,
    data_escalacao: data14dias,
    contador_lembretes: 0,
    email_gestor: 'SEU_EMAIL_GESTOR@empresa.com'
  }
}];

// Parseia a aba Checklists e filtra apenas os pendentes
const data = $input.first().json;
if (!data.values || data.values.length <= 1) {
  return [{json: {nenhum_pendente: true, mensagem: 'Nenhum checklist pendente encontrado.'}}];
}
const headers = data.values[0];
const rows = data.values.slice(1);
const items = rows.map(row => {
  const obj = {};
  headers.forEach((h, i) => { obj[String(h)] = row[i]; });
  return obj;
}).filter(r => r.Status === 'AGUARDANDO_RESPOSTA');

if (!items.length) return [{json: {nenhum_pendente: true, mensagem: 'Nenhum checklist aguardando resposta.'}}];

// Calcular dias desde o envio para cada checklist
const agora = new Date();
return items.map(item => {
  const dataEnvio = new Date(item.Data_Envio || item.Data_Criacao || agora);
  const diasDesdeEnvio = Math.floor((agora - dataEnvio) / 86400000);
  let acaoNecessaria = 'NENHUMA';
  if (diasDesdeEnvio >= 14) acaoNecessaria = 'ESCALACAO';
  else if (diasDesdeEnvio >= 7) acaoNecessaria = 'LEMBRETE_2';
  else if (diasDesdeEnvio >= 3) acaoNecessaria = 'LEMBRETE_1';
  return {json: {...item, dias_desde_envio: diasDesdeEnvio, acao_necessaria: acaoNecessaria}};
});

// Analisa a completude do checklist respondido pelo fornecedor
const resp = $input.first().json.body || $input.first().json;

// Determinar completude
const itensConcluidos = resp.Itens_Concluidos || resp.itens_concluidos || [];
const totalItens = resp.Total_Itens || itensConcluidos.length || 0;
const itensConcluidos_n = Array.isArray(itensConcluidos) ? itensConcluidos.length : Number(itensConcluidos) || 0;
const pct_conclusao = totalItens > 0 ? Math.round((itensConcluidos_n / totalItens) * 100) : 0;
const completo = pct_conclusao >= 90; // 90% ou mais = considerado completo
const temDesvios = resp.Desvios_Encontrados === 'SIM' || resp.desvios_encontrados === true;

// Status da resposta
let statusResposta = 'INCOMPLETO';
if (completo && !temDesvios) statusResposta = 'COMPLETO_OK';
else if (completo && temDesvios) statusResposta = 'COMPLETO_COM_DESVIOS';
else if (pct_conclusao >= 50) statusResposta = 'PARCIAL';

// Detectar se a resposta revela uma nova ocorrencia ou aprendizado
// Se o fornecedor relata desvio NAO previsto no checklist = novo aprendizado
const novoAprendizado = temDesvios && (resp.Desvio_Nao_Previsto === 'SIM' || resp.desvio_nao_previsto === true);

console.log('Resposta recebida. Checklist:', resp.Checklist_ID, '| Completude:', pct_conclusao + '%', '| Status:', statusResposta);

return [{
  json: {
    ...resp,
    pct_conclusao,
    completo,
    tem_desvios: temDesvios,
    status_resposta: statusResposta,
    novo_aprendizado: novoAprendizado,
    data_resposta: new Date().toISOString()
  }
}];

const resp = $input.first().json;
// Registrar como caso de aprendizado se houve desvio nao previsto
if (!resp.novo_aprendizado) {
  return [{json: {...resp, registrou_aprendizado: false}}];
}

console.log('NOVO APRENDIZADO detectado no checklist', resp.Checklist_ID, '- Desvio não previsto reportado pelo fornecedor.');

return [{
  json: {
    ...resp,
    registrou_aprendizado: true,
    aprendizado: {
      checklist_id: resp.Checklist_ID || '',
      data: new Date().toISOString(),
      fornecedor: resp.Fornecedor || '',
      part_number: resp.Part_Number || '',
      descricao_desvio: resp.Descricao_Desvio || resp.Observacoes || '',
      tipo: 'DESVIO_NAO_PREVISTO_EM_CHECKLIST',
      status_validacao: 'PENDENTE',
      impacto_nos_modelos: 'A ser avaliado pelo engenheiro de qualidade'
    }
  }
}];
